alendar.scss","webpack://phoenix-react/./src/assets/scss/theme/_chat.scss","webpack://phoenix-react/./src/assets/scss/theme/_typing.scss","webpack://phoenix-react/./src/assets/scss/theme/_crm.scss","webpack://phoenix-react/./src/assets/scss/theme/_auth-card.scss","webpack://phoenix-react/./src/assets/scss/theme/_pricing.scss"],"sourcesContent":["/* -------------------------------------------------------------------------- */\n/*                                 Theme                                      */\n/* -------------------------------------------------------------------------- */\n\n@import '~bootstrap/scss/_functions';\n@import 'theme/functions';\n\n@import 'user-variables';\n@import 'theme/variables';\n\n@import 'theme/maps';\n@import '~bootstrap/scss/maps';\n\n@import '~bootstrap/scss/mixins';\n@import 'theme/mixins';\n\n@import 'theme/_utilities';\n@import '~bootstrap/scss/variables';\n// @import '~bootstrap/scss/root';\n@import 'theme/root';\n\n/*-----------------------------------------------\n|   Bootstrap Styles\n-----------------------------------------------*/\n@import 'bootstrap';\n\n/*-----------------------------------------------\n|   Theme Styles\n-----------------------------------------------*/\n@import 'theme/theme';\n","/* prettier-ignore */\n@use 'sass:math';\n@import 'colors';\n$prefix: 'phoenix-';\n// Grid containers\n//\n// Define the maximum width of `.container` for different screen sizes.\n// scss-docs-start container-max-widths\n$container-max-widths: () !default;\n$container-max-widths: map-merge(\n  (\n    sm: 540px,\n    md: 720px,\n    lg: 960px,\n    xl: 1184px,\n    xxl: 1678px\n  ),\n  $container-max-widths\n);\n\n$container-small-max-widths: (\n  sm: 540px,\n  md: 720px,\n  lg: 960px,\n  xl: 1216px\n);\n\n$grid-breakpoints: () !default;\n$grid-breakpoints: map-merge(\n  (\n    xs: 0,\n    sm: 576px,\n    md: 768px,\n    lg: 992px,\n    xl: 1200px,\n    xxl: 1540px\n  ),\n  $grid-breakpoints\n);\n\n//*-----------------------------------------------\n//|   Gutter\n//-----------------------------------------------*/\n$grid-gutter-width: 2rem !default;\n\n// Customize the light and dark text colors for use in our color contrast function.\n// $color-contrast-dark: $gray-800 !default;\n$color-contrast-dark: $black !default;\n$color-contrast-light: $white !default;\n\n// Min contrast ratio\n$min-contrast-ratio: 2 !default;\n\n//*-----------------------------------------------\n//|   Brand colors\n//-----------------------------------------------*/\n$linkedin: #0077b5 !default;\n$facebook: #3c5a99 !default;\n$twitter: #1da1f2 !default;\n$google-plus: #dd4b39 !default;\n$github: #333333 !default;\n$youtube: #ff0001 !default;\n\n$brand-colors: () !default;\n$brand-colors: map-merge(\n  (\n    'facebook': $facebook,\n    'google-plus': $google-plus,\n    'twitter': $twitter,\n    'linkedin': $linkedin,\n    'youtube': $youtube,\n    'github': $github\n  ),\n  $brand-colors\n);\n\n//*-----------------------------------------------\n//|   Border\n//-----------------------------------------------*/\n$border-width: 1px !default;\n$border-color: var(--#{$prefix}gray-200);\n\n// Options\n//\n// Quickly modify global styling by enabling or disabling optional features.\n\n$enable-shadows: true !default;\n$enable-negative-margins: true !default;\n\n// $component-active-color: var(--#{$prefix}white) !default;\n// $component-active-bg: var(--#{$prefix}primary) !default;\n\n//*-----------------------------------------------\n//|   Shadow\n//-----------------------------------------------*/\n$box-shadow: 0px 2px 4px -2px rgba(36, 40, 46, 0.08);\n// $box-shadow-sm: 0px 2px 4px -2px rgba(36, 40, 46, 0.08);\n// $box-shadow-lg: var(--#{$prefix}box-shadow-lg) !default;\n// $box-shadow-inset: 0px 0px 0px 4px rgba(56, 116, 255, 0.2) !default;\n$box-shadow-gray-400: 0px 4px 8px -6px rgba(36, 40, 46, 0.03),\n  0px 16px 8px -4px rgba(36, 40, 46, 0.03);\n\n//*-----------------------------------------------\n//|   Spacing\n//----------------------------------------------\n\n$spacer: 1rem !default;\n$spacers: () !default;\n\n$spacers: map-merge(\n  (\n    0: 0,\n    1: $spacer * 0.25,\n    2: $spacer * 0.5,\n    3: $spacer,\n    4: $spacer * 1.5,\n    5: $spacer * 2,\n    6: $spacer * 2.5,\n    7: $spacer * 3,\n    8: $spacer * 3.5,\n    9: $spacer * 4,\n    10: $spacer * 4.5,\n    11: $spacer * 5,\n    12: $spacer * 6,\n    13: $spacer * 6.5,\n    14: $spacer * 7,\n    15: $spacer * 7.5\n  ),\n  $spacers\n);\n\n//*-----------------------------------------------\n//|   Body\n//-----------------------------------------------*/\n$body-bg: $gray-soft !default;\n$body-color: $gray-900 !default;\n\n//*-----------------------------------------------\n//|   Link\n//-----------------------------------------------*/\n$link-decoration: none !default;\n$link-hover-decoration: underline !default;\n\n//*-----------------------------------------------\n//|   Components\n//-----------------------------------------------*/\n$border-radius-sm: 0.25rem !default;\n$border-radius: 0.375rem !default;\n$border-radius-lg: 0.5rem !default;\n\n//*-----------------------------------------------\n//|   Fonts Families\n//-----------------------------------------------*/\n$font-family-sans-serif: 'Nunito Sans', -apple-system, BlinkMacSystemFont,\n  'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif, 'Apple Color Emoji',\n  'Segoe UI Emoji', 'Segoe UI Symbol' !default;\n$font-family-monospace: 'SFMono-Regular', Menlo, Monaco, Consolas,\n  'Liberation Mono', 'Courier New', monospace !default;\n$font-family-base: $font-family-sans-serif;\n\n//*-----------------------------------------------\n//|   Fonts\n//-----------------------------------------------*/\n$type-scale: 1.25 !default;\n$font-size-base: 1rem !default;\n$font-sizes: (\n  '11': math.div(1, pow($type-scale, 3)) * $font-size-base,\n  // 8.19px\n  '10': math.div(1, pow($type-scale, 2)) * $font-size-base,\n  // 10.24px\n  '9': math.div(1, $type-scale) * $font-size-base,\n  // 12.80px\n  8: $font-size-base,\n  // 16px\n  7: pow($type-scale, 1) * $font-size-base,\n  //20px\n  6: pow($type-scale, 2) * $font-size-base,\n  //25px\n  5: pow($type-scale, 3) * $font-size-base,\n  // 31.25px\n  4: pow($type-scale, 4) * $font-size-base,\n  // 39.06px\n  3: pow($type-scale, 5) * $font-size-base,\n  // 48.83px\n  2: pow($type-scale, 6) * $font-size-base,\n  // 61.04px\n  1: pow($type-scale, 7) * $font-size-base // 76.29px\n) !default;\n\n$font-size-sm: $font-size-base * 0.875 !default;\n$font-size-lg: $font-size-base * 1.2 !default;\n$font-weight-thin: 100 !default;\n$font-weight-lighter: 200 !default;\n$font-weight-light: 300 !default;\n$font-weight-normal: 400 !default;\n$font-weight-medium: 500 !default;\n$font-weight-semi-bold: 600 !default;\n$font-weight-bold: 700 !default;\n$font-weight-bolder: 800 !default;\n$font-weight-black: 900 !default;\n\n$line-height-base: 1.49 !default;\n$line-height-sm: 1.2 !default;\n$line-height-lg: 1.4 !default;\n\n$h1-font-size: map_get($font-sizes, 4) !default;\n$h2-font-size: map_get($font-sizes, 5) !default;\n$h3-font-size: map_get($font-sizes, 6) !default;\n$h4-font-size: map_get($font-sizes, 7) !default;\n$h5-font-size: map_get($font-sizes, 8) !default;\n$h6-font-size: map_get($font-sizes, '9') !default;\n\n$headings-font-family: $font-family-sans-serif !default;\n$headings-font-weight: $font-weight-bold !default;\n$headings-color: var(--#{$prefix}1100) !default;\n$headings-line-height: 1 !default;\n$headings-margin-bottom: map-get($spacers, 1) !default;\n\n// scss-docs-start display-headings\n$display-font-sizes: () !default;\n$display-font-sizes: map-merge(\n  (\n    1: map_get($font-sizes, 1),\n    2: map_get($font-sizes, 2),\n    3: map_get($font-sizes, 3),\n    4: map_get($font-sizes, 4),\n    5: map_get($font-sizes, 5),\n    6: map_get($font-sizes, 6)\n  ),\n  $display-font-sizes\n);\n\n$display-font-weight: $font-weight-normal !default;\n// scss-docs-end display-headings\n\n$lead-font-size: map-get($font-sizes, 7) !default;\n$lead-font-weight: $font-weight-semi-bold !default;\n\n$small-font-size: 75% !default;\n\n$text-muted: $gray-500 !default;\n\n$blockquote-font-size: $font-size-lg !default;\n\n//*-----------------------------------------------\n//|   Accordion\n//-----------------------------------------------*/\n// $accordion-icon-active-color: $body-color;\n$accordion-padding-y: map-get($spacers, 2) !default;\n$accordion-padding-x: 0 !default;\n$accordion-border-radius: 0 !default;\n$accordion-bg: transparent !default;\n$accordion-color: $gray-1000 !default;\n$accordion-button-active-bg: transparent !default;\n$accordion-border-width: 0 !default;\n$accordion-button-color: $primary !default;\n$accordion-button-active-color: $gray-1100 !default;\n$accordion-icon-color: $primary !default;\n$accordion-icon-active-color: $primary !default;\n$accordion-button-icon: url(\"data:image/svg+xml,%3Csvg aria-hidden='true' focusable='false' role='img' xmlns='http://www.w3.org/2000/svg' viewBox='-200 -200 900 900'%3E%3Cpath fill='#{$accordion-icon-color}' d='M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z'%3E%3C/path%3E%3C/svg%3E\");\n$accordion-button-active-icon: url(\"data:image/svg+xml,%3Csvg aria-hidden='true' focusable='false' role='img' xmlns='http://www.w3.org/2000/svg' viewBox='-200 -200 900 900'%3E%3Cpath fill='#{$accordion-icon-active-color}' d='M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z'%3E%3C/path%3E%3C/svg%3E\");\n\n//*-----------------------------------------------\n//|   Tables\n//-----------------------------------------------*/\n$table-color: var(--#{$prefix}gray-900);\n$table-border-color: $gray-200 !default;\n$table-head-bg: $gray-900 !default;\n$table-head-color: $dark !default;\n$table-th-font-weight: $font-weight-bolder;\n$table-dark-bg: $gray-1000 !default;\n$table-dark-border-color: lighten($gray-1000, 7.5%) !default;\n$table-striped-order: even !default;\n// $table-accent-bg: $gray-100 !default;\n$table-cell-padding-y: 1rem !default;\n// $table-cell-padding-y-sm: 0.5rem !default;\n$table-group-separator-color: inherit !default;\n\n$table-striped-color: var(--#{$prefix}gray-1000);\n$table-striped-bg: rgba(var(--#{$prefix}1100-rgb), 0.07);\n$table-hover-bg: rgba(var(--#{$prefix}primary-600-rgb), 0.07);\n$table-hover-color: var(--#{$prefix}black);\n\n//*-----------------------------------------------\n//|   Buttons\n//-----------------------------------------------*/\n$btn-link-disabled-color: $gray-400 !default;\n$btn-disabled-opacity: 0.3 !default;\n$btn-box-shadow: inset 0 1px 0 rgba($white, 0), 0 1px 1px rgba($black, 0) !default;\n$btn-font-weight: $font-weight-bold !default;\n$btn-line-height: 1.2 !default;\n// $btn-border-width: 0 !default;\n\n// $btn-font-size: map_get($font-sizes, '-1') !default;\n$btn-border-radius: 0.375rem !default;\n$btn-border-radius-sm: 0.375rem !default;\n$btn-border-radius-lg: 0.375rem !default;\n\n$btn-pill-border-radius: 1.5rem !default;\n\n// $btn-padding-y-sm: 0.59375rem !default;\n// $btn-font-size-sm: map_get($font-sizes, '-2') !default;\n\n// $btn-padding-y-lg: 0.875rem !default;\n// $btn-font-size-lg: map_get($font-sizes, 0) !default;\n\n/* ----------------------------- Phoenix-buttons ---------------------------- */\n$btn-phoenix-border-color: var(--#{$prefix}gray-200);\n\n//*-----------------------------------------------\n//|   Buttons and Forms\n//-----------------------------------------------*/\n\n$input-btn-padding-y: 0.625rem !default;\n$input-btn-padding-x: 1.5rem !default;\n\n$input-padding-y-sm: 0.375rem;\n$input-padding-y: 0.5rem;\n$input-padding-y-lg: 0.75rem;\n\n$input-btn-font-size: map-get($font-sizes, '9');\n$input-btn-font-size-sm: map-get($font-sizes, '9');\n$input-btn-font-size-lg: map-get($font-sizes, 8);\n$input-btn-line-height: $line-height-base;\n$input-font-weight: $font-weight-semi-bold;\n\n$input-btn-padding-y-sm: 0.5rem !default;\n$input-btn-padding-x-sm: 1rem !default;\n\n$input-btn-padding-y-lg: 0.875rem !default;\n$input-btn-padding-x-lg: 1.5rem !default;\n\n$input-box-shadow: inset 0 1px 2px transparent !default;\n$btn-reveal-hover-shadow: 0 0 0 1px rgba(43, 45, 80, 0.1),\n  0 2px 5px 0 rgba(43, 45, 80, 0.08), 0 1px 1.5px 0 rgba($black, 0.07),\n  0 1px 2px 0 rgba($black, 0.08) !default;\n$btn-font-weight: $font-weight-medium !default;\n$input-btn-focus-blur: 0 !default;\n$btn-focus-width: 0 !default;\n$btn-focus-box-shadow: 0 0 0 0.25rem transparent !default;\n$btn-active-box-shadow: inset 0 3px 5px rgba($black, 0) !default;\n\n//*-----------------------------------------------\n//|   Forms\n//-----------------------------------------------*/\n\n$input-padding-x: 1rem;\n$input-padding-x-lg: 1rem;\n\n$input-disabled-bg: rgba(var(--#{$prefix}gray-100-rgb), 0.7) !default;\n$input-disabled-color: var(--#{$prefix}gray-500) !default;\n$input-group-addon-bg: $gray-100 !default;\n$input-disabled-group-addon-bg: $input-disabled-bg !default;\n$input-disabled-group-addon-color: $input-disabled-color !default;\n$input-border-color: var(--#{$prefix}input-border-color) !default;\n$input-color: var(--#{$prefix}gray-900) !default;\n$input-placeholder-color: $gray-400;\n\n$input-border-radius: 0.375rem !default;\n$input-border-radius-sm: 0.375rem !default;\n$input-border-radius-lg: 0.375rem !default;\n\n// $form-floating-padding-y: 0.645rem;\n$form-floating-input-padding-t: 22.5px !default;\n$form-floating-input-padding-b: 9.5px !default;\n$form-floating-label-transform: scale(0.85) translateY(-0.4rem)\n  translateX(0.15rem);\n$form-floating-height: add(2.875rem, 2px) !default;\n\n$form-check-margin-bottom: 0.34375rem !default;\n$form-label-font-size: map-get($font-sizes, '10') !default;\n$form-label-font-style: null !default;\n