em {\r\n      .nav-link {\r\n        &.active {\r\n          background: var(--#{$prefix}200);\r\n          border-radius: 6px;\r\n        }\r\n        &.unread {\r\n          .name {\r\n            color: var(--#{$prefix}1100) !important;\r\n            font-weight: $font-weight-bold !important;\r\n          }\r\n          .message {\r\n            color: var(--#{$prefix}800) !important;\r\n            font-weight: $font-weight-semi-bold !important;\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n  .chat-message {\r\n    .actions {\r\n      box-shadow: 0px 0px 32px rgba(0, 0, 0, 0.12),\r\n        0px 8px 24px -4px rgba(36, 40, 46, 0.12);\r\n    }\r\n    .chat-message-content {\r\n      max-width: calc(100% - 4rem);\r\n      &.received {\r\n        max-width: calc(100% - 6rem);\r\n      }\r\n      // .attachments {\r\n      img {\r\n        // max-width: min(100%, 200px);\r\n        width: 100%;\r\n        max-width: 200px;\r\n      }\r\n      // }\r\n      @include media-breakpoint-up(sm) {\r\n        max-width: calc(100% - 10rem);\r\n        &.received {\r\n          max-width: calc(100% - 11rem);\r\n        }\r\n      }\r\n    }\r\n\r\n    .received-message-content {\r\n      position: relative;\r\n      border-radius: $border-radius;\r\n      padding: map-get($spacers, 3);\r\n      &:not(&.attachments) {\r\n        &:after {\r\n          content: ' ';\r\n          position: absolute;\r\n          width: 0;\r\n          height: 0;\r\n          left: -10px;\r\n          right: auto;\r\n          top: 0px;\r\n          bottom: auto;\r\n          border: 10px solid;\r\n          border-color: var(--#{$prefix}white) transparent transparent\r\n            transparent;\r\n        }\r\n        &:before {\r\n          content: ' ';\r\n          position: absolute;\r\n          width: 0;\r\n          height: 0;\r\n          left: -12px;\r\n          right: auto;\r\n          top: -1px;\r\n          bottom: auto;\r\n          border: 11px solid;\r\n          border-color: var(--#{$prefix}200) transparent transparent transparent;\r\n        }\r\n      }\r\n    }\r\n    .sent-message-content {\r\n      position: relative;\r\n      &:not(&.attachments) {\r\n        border-radius: $border-radius;\r\n        padding: map-get($spacers, 3);\r\n        color: var(--#{$prefix}white);\r\n        background: var(--#{$prefix}primary);\r\n        &:after {\r\n          content: ' ';\r\n          position: absolute;\r\n          width: 0;\r\n          height: 0;\r\n          left: auto;\r\n          right: -12px;\r\n          top: auto;\r\n          bottom: 0;\r\n          border: 12px solid;\r\n          border-color: transparent transparent var(--#{$prefix}primary)\r\n            transparent;\r\n        }\r\n      }\r\n    }\r\n  }\r\n  .chat-textarea {\r\n    max-height: 6.25rem;\r\n    &[contenteditable='true']:empty:before {\r\n      content: attr(placeholder);\r\n      pointer-events: none;\r\n      color: var(--#{$prefix}gray-500);\r\n      font-weight: $font-weight-semi-bold;\r\n    }\r\n  }\r\n}\r\n\r\n.chat-search-box {\r\n  box-shadow: 0px 16px 80px -4px rgba(36, 40, 46, 0.3);\r\n  .form-icon {\r\n    top: 1.25rem !important;\r\n  }\r\n}\r\n\r\n#searchBoxModal {\r\n  .modal-content {\r\n    background-color: transparent;\r\n  }\r\n  .modal-backdrop {\r\n    background-color: transparent;\r\n  }\r\n}\r\n",".dot-typing {\r\n  position: relative;\r\n  left: -9999px;\r\n  width: 5px;\r\n  height: 5px;\r\n  border-radius: 5px;\r\n  background-color: #9880ff;\r\n  color: #9880ff;\r\n  box-shadow: 9984px 0 0 0 #9880ff, 9999px 0 0 0 #9880ff, 10014px 0 0 0 #9880ff;\r\n  animation: dot-typing 1.5s infinite linear;\r\n}\r\n\r\n@keyframes dot-typing {\r\n  0% {\r\n    box-shadow: 9984px 0 0 0 #9880ff, 9999px 0 0 0 #9880ff,\r\n      10014px 0 0 0 #9880ff;\r\n  }\r\n\r\n  16.667% {\r\n    box-shadow: 9984px -10px 0 0 #9880ff, 9999px 0 0 0 #9880ff,\r\n      10014px 0 0 0 #9880ff;\r\n  }\r\n\r\n  33.333% {\r\n    box-shadow: 9984px 0 0 0 #9880ff, 9999px 0 0 0 #9880ff,\r\n      10014px 0 0 0 #9880ff;\r\n  }\r\n\r\n  50% {\r\n    box-shadow: 9984px 0 0 0 #9880ff, 9999px -10px 0 0 #9880ff,\r\n      10014px 0 0 0 #9880ff;\r\n  }\r\n\r\n  66.667% {\r\n    box-shadow: 9984px 0 0 0 #9880ff, 9999px 0 0 0 #9880ff,\r\n      10014px 0 0 0 #9880ff;\r\n  }\r\n\r\n  83.333% {\r\n    box-shadow: 9984px 0 0 0 #9880ff, 9999px 0 0 0 #9880ff,\r\n      10014px -10px 0 0 #9880ff;\r\n  }\r\n\r\n  100% {\r\n    box-shadow: 9984px 0 0 0 #9880ff, 9999px 0 0 0 #9880ff,\r\n      10014px 0 0 0 #9880ff;\r\n  }\r\n}\r\n\r\n$dot-width: 10px;\r\n$dot-color: #3b5998;\r\n$speed: 1.5s;\r\n\r\n.typing {\r\n  position: relative;\r\n\r\n  span {\r\n    // content: '';\r\n    display: inline-block;\r\n    animation: blink $speed infinite;\r\n    animation-fill-mode: both;\r\n    height: $dot-width;\r\n    width: $dot-width;\r\n    background: $dot-color;\r\n    // position: absolute;\r\n    // left: 0;\r\n    // top: 0;\r\n    border-radius: 50%;\r\n\r\n    &:nth-child(2) {\r\n      animation-delay: 0.2s;\r\n      margin-left: $dot-width * 1.5;\r\n    }\r\n\r\n    &:nth-child(3) {\r\n      animation-delay: 0.4s;\r\n      margin-left: $dot-width * 3;\r\n    }\r\n  }\r\n}\r\n\r\n@keyframes blink {\r\n  0% {\r\n    opacity: 0.1;\r\n  }\r\n  20% {\r\n    opacity: 1;\r\n  }\r\n  100% {\r\n    opacity: 0.1;\r\n  }\r\n}\r\n",".lead-details-container {\r\n  .nav-underline-scrollspy {\r\n    z-index: 1014;\r\n    top: calc(var(--#{$prefix}navbar-top-height) + 1px);\r\n  }\r\n}\r\n.sticky-leads-sidebar {\r\n  position: sticky;\r\n  z-index: 1015;\r\n  top: calc(var(--#{$prefix}navbar-top-height) + 21px);\r\n}\r\n.leads-table {\r\n  th {\r\n    position: relative;\r\n    &::after {\r\n      position: absolute;\r\n      top: 35%;\r\n    }\r\n  }\r\n}\r\n\r\n.lead-details-offcanvas {\r\n  max-width: 350px;\r\n  top: var(--#{$prefix}navbar-top-height) !important;\r\n  height: calc(100vh - var(--#{$prefix}navbar-top-height));\r\n  padding: map-get($spacers